llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C39"],
      "claim": "The query is orlistat, a highly lipophilic N-formyl-leucine beta-lactone ester; the closest supplied analog, testosterone undecanoate (a long-chain lipophilic ester prodrug), has mean absolute oral bioavailability of only 6.8 ± 3.3% in humans, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Dimethandrolone undecanoate, another long-chain ester prodrug, shows poor and inconsistent oral bioavailability in men, supporting that this chemical class is poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Batimastat, a high-molecular-weight poorly soluble peptidomimetic, has poor oral bioavailability in humans, consistent with low F for large lipophilic molecules with solubility limitations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Colesevelam, a large non-absorbable polymer, has negligible systemic bioavailability (<0.04%), illustrating that high-molecular-weight, poorly absorbed entities can have F far below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Nimodipine, a lipophilic drug with extensive first-pass metabolism, has absolute oral bioavailability <5% in humans, supporting low F for highly lipophilic, metabolically labile molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query SMILES corresponds to orlistat, a GI-targeted lipase inhibitor designed for minimal systemic absorption. Its high lipophilicity, high molecular weight, and ester/lactone prodrug character, together with consistent evidence from lipophilic ester prodrugs and poorly absorbed high-MW drugs, support very low oral bioavailability, far below the 20% threshold.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for orlistat is included in the supplied evidence; all records are from structurally related but distinct molecules.",
    "Some dihydropyridine records report F values near or above 20%, but these are outliers and not transferable to the beta-lactone ester scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

